effect.shader:
float rand(vec2 c){ return fract(sin(dot(c,vec2(12.9898,78.233)))*43758.5453); }
void main(){
    float sc = size;
    vec2 g = acScreenNorm*sc;
    vec2 ip = floor(g);
    vec2 fp = fract(g);
    float md = 9.0;
    vec2 best = ip;
    for(int y=-1;y<=1;y++){
        for(int x=-1;x<=1;x++){
            vec2 nb = vec2(float(x),float(y));
            vec2 o = vec2(rand(ip+nb), rand(ip+nb+3.3));
            vec2 diff = nb + o - fp;
            float dd = dot(diff,diff);
            if(dd<md){ md=dd; best = ip+nb+o; }
        }
    }
    gl_FragColor = texture2DCv(inputImg.texture, clamp(best/sc,0.0,1.0));
}
